ROOT=Path(__file__).resolve().parents[3]
OUT=Path(__file__).resolve().parents[1]
SRC=OUT/'source'; FIG=OUT/'figures'; QA=OUT/'qa'; LATEX=OUT/'latex'
DATA=json.loads((ROOT/'results/combined/results.json').read_text())
CHECK=json.loads((ROOT/'results/lora-controls/checked-results.json').read_text())
LIMIT=json.loads((ROOT/'results/lora-limit-2b/completed-464/summary.json').read_text())
S={(x['model'],x['method']):x for x in DATA['summaries']}
MODELS=['0.8b','2b','4b']; BUDGET={'0.8b':'512','2b':'1024','4b':'2048'}
NAME={'on':'ON','off':'OFF','lora1':'LoRA alone','lora1-off':'LoRA + OFF','brief':'Brief prompt','lora2':'LoRA-2'}
def label(m): return NAME.get(m,m.replace('lora1-limit','LoRA + limit ').replace('limit','Limit '))
def pct(v): return f'{100*v:.1f}%'
def ci(v,percent=True): return '['+', '.join(f'{x*100:.1f}'+('%' if percent else '') for x in v)+']'
def get(m,k): return S[(m,k)]
def full(m): return [get(m,k) for k in ['on','off','limit'+BUDGET[m],'lora1','lora1-off','lora1-limit'+BUDGET[m]]]

