def clean(s):
 return s.replace('—','-').replace('–','-').replace('’',"'").replace('“','"').replace('”','"').replace('≤','<=').replace('→',' to ')
def parse(md):
 blocks=[]
 for x in re.split(r'\n\s*\n',md.strip()):
  x=x.strip()
  if not x:continue
  if x.startswith('# '):blocks.append(('chapter',x[2:]))
  elif x.startswith('## '):blocks.append(('heading',x[3:]))
  elif x.startswith('[[FIG:'):blocks.append(('figure',x[6:-2]))
  elif x.startswith('[[TABLE:'):blocks.append(('table',x[8:-2]))
  else:blocks.append(('p',clean(x.replace('\n',' '))))
 return blocks

def number_items(blocks):
 order=[];f=0;t=0
 for kind,txt in blocks:
  if kind=='figure':f+=1;FIG_NO.setdefault(txt,f)
  if kind=='table':t+=1;TAB_NO.setdefault(txt,t)
  for match in re.findall(r'\[@([^]]+)\]',txt):
   for key in match.replace('@','').split(';'):
    if key not in order:order.append(key)
 return {k:i+1 for i,k in enumerate(order)}

def prose(s,refs,latex=False):
 def cit(m):
  keys=m[1].replace('@','').split(';')
  return (r'\cite{'+','.join(keys)+'}') if latex else ', '.join(f'[{refs[k]}]' for k in keys)
 s=re.sub(r'\[@([^]]+)\]',cit,s)
 for kind,mapping in [('FIGREF',FIG_NO),('TABREF',TAB_NO)]:
  s=re.sub(r'\[\['+kind+r':([^]]+)\]\]',lambda m:str(mapping[m[1]]),s)
 return s

